mapper.select:
SELECT m.member_id, m.site_code, m.login_id, m.member_name, m.email,
       COALESCE(m.last_login_at, m.created_at) AS base_at
FROM tb_member m
WHERE m.delete_yn = 'N' AND m.status = 'ACTIVE'
  AND COALESCE(m.last_login_at, m.created_at) >= #{from}
  AND COALESCE(m.last_login_at, m.created_at) < #{to}
  AND NOT EXISTS (SELECT 1 FROM tb_member_dormant_notice n
                   WHERE n.member_id = m.member_id AND n.stage = #{stage})
ORDER BY base_at
LIMIT #{limit}

SELECT member_id, site_code, login_id, member_name, email,
       dormant_at AS base_at
FROM tb_member_dormant
WHERE delete_yn = 'N' AND restored_at IS NULL AND dormant_at < #{cutoff}
ORDER BY dormant_at
LIMIT #{limit}

SELECT member_id FROM tb_member_withdraw
WHERE retention_expire_at IS NOT NULL AND retention_expire_at < #{now}
ORDER BY retention_expire_at
LIMIT #{limit}
